#!/usr/bin/env node
/**
 * Tray + packaging icons.
 * Canonical in-app mark: src/components/icons/GrokMark2Icon.tsx
 * All packaging outputs are generated by scripts/gen-packaging-icons.py
 * (soft charcoal disc + light head + dark tilted eye slits — not the
 * inverted outline/antenna mark, not purple charts).
 */
import { spawnSync } from "child_process";
import { dirname, join } from "path";
import { fileURLToPath } from "url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const script = join(root, "scripts/gen-packaging-icons.py");
const r = spawnSync("python3", [script], { stdio: "inherit", cwd: root });
process.exit(r.status ?? 1);
